module.exports["resave_tiddler"].definition = {
	"description": "Rewrite a tiddler's .tid file using current FileSystemPaths. Relocates the file if path rules changed. Preserves modified/modifier by default. Refuses on shadow-only, plugin/theme/language, or .multids-bundled tiddlers.",
	"inputSchema": {
		"type": "object",
		"properties": {
			"title": {
				"type": "string",
				"maxLength": 1024,
				"description": "Tiddler title (max 1024 chars)"
			},
			"preserve_timestamps": {
				"type": "boolean",
				"default": true,
				"description": "Keep modified/modifier unchanged (default). Set false to stamp current time and user."
			},
			"strip_redundant": {
				"type": "boolean",
				"default": true,
				"description": "Drop 'revision' and drop 'type' when it equals text/vnd.tiddlywiki (default)."
			},
			"dry_run": {
				"type": "boolean",
				"default": false,
				"description": "Report old/new path and fields that would be stripped; do not write."
			}
		},
		"required": [
			"title"
		]
	},
	"write": true
};
","type":"application/javascript","module-type":"mcp-handler"},"$:/core/modules/commands/inspect/handlers/filesystem.js":{"title":"$:/core/modules/commands/inspect/handlers/filesystem.js","text":"/*\
title: $:/core/modules/commands/inspect/handlers/filesystem.js
type: application/javascript
module-type: mcp-handler

MCP tool handlers for filesystem and build operations.

\*/

"use strict";

var fs = $tw.node ? require("fs") : null,
	path = $tw.node ? require("path") : null;

var shared = require("$:/core/modules/commands/inspect/handlers/shared.js");

var addToWikiSilently = shared.addToWikiSilently;

var MAX_UPLOAD_BYTES = 50 * 1024 * 1024;
// Base64 inflates payload by ~4/3. Cap the encoded length so we reject
// oversized payloads before allocating the decoded buffer.
var MAX_UPLOAD_BASE64_LENGTH = Math.ceil(MAX_UPLOAD_BYTES / 3) * 4;

// Recursively check whether any wiki in the includeWikis tree has
// `retain-original-tiddler-path: true`. Each includeWikis entry is
// a path string or `{path: "..."}` object, resolved relative to the
// referring wiki's directory. Returns true on first hit.
function wikiInfoHasRetain(info, basePath, seen) {
	if(!info || !basePath) return false;
	if(info.config && info.config["retain-original-tiddler-path"]) return true;
	if(!info.includeWikis || !info.includeWikis.length) return false;
	seen = seen || Object.create(null);
	for(var i = 0; i < info.includeWikis.length; i++) {
		var inc = info.includeWikis[i];
		var incPath = (typeof inc === "string") ? inc : (inc && inc.path);
		if(!incPath) continue;
		try {
			var resolvedDir = path.resolve(basePath, incPath);
			if(seen[resolvedDir]) continue;
			seen[resolvedDir] = true;
			var infoPath = path.resolve(resolvedDir, "tiddlywiki.info");
			if(!fs.existsSync(infoPath)) continue;
			var subInfo = JSON.parse(fs.readFileSync(infoPath, "utf8"));
			if(wikiInfoHasRetain(subInfo, resolvedDir, seen)) return true;
		} catch(e) { /* ignore: continue to next include */ }
	}
	return false;
}

// Change log: accumulates $tw.wiki changes between reload_tiddlers calls.
// Capped at CHANGE_LOG_MAX entries to bound memory if the user never calls
// reload_tiddlers (eg an MCP-only workflow that mostly writes). On overflow
// the oldest entry is dropped (object insertion order in modern engines).
var changeLog = {};
var changeLogActive = false;
var CHANGE_LOG_MAX = 1000;
// Per-reload title set. The change listener runs on $tw.utils.nextTick
// AFTER reload_tiddlers returns, so events from the reload's own
// addTiddler / deleteTiddler calls would otherwise land in changeLog and
// show up as bogus entries on the next call. While reloadOwnedTitles is
// non-null, the listener skips titles in this set. Cleared via setImmediate
// (which fires after nextTick) so the events have a chance to be filtered.
var reloadOwnedTitles = null;

function startChangeLog() {
	if(changeLogActive) {
		return;
	}
	changeLogActive = true;
	$tw.wiki.addEventListener("change", function(changes) {
		var titles = Object.keys(changes);
		for(var i = 0; i < titles.length; i++) {
			var title = titles[i];
			if(title.indexOf("$:/") === 0) {
				continue;
			}
			if(reloadOwnedTitles && reloadOwnedTitles[title]) {
				continue;
			}
			// Cap: when adding a new title would exceed the limit, drop the
			// oldest (first-inserted) entry. Existing-title updates don't grow
			// the map, so no cap check needed there.
			if(changeLog[title] === undefined) {
				var existingKeys = Object.keys(changeLog);
				if(existingKeys.length >= CHANGE_LOG_MAX) {
					delete changeLog[existingKeys[0]];
				}
			}
			if(changes[title].deleted) {
				changeLog[title] = "deleted";
			} else if(changeLog[title] === undefined) {
				changeLog[title] = "added";
			} else {
				changeLog[title] = "updated";
			}
		}
	});
}

module.exports = {
	"reload_tiddlers": function(args) {
		var scope = (args && args.scope) || "tiddlers";
		var messages = [];
		var dualScope = (scope === "all");

		// Reload edition tiddlers
		if(scope === "tiddlers" || scope === "all") {
			if(dualScope) messages.push("=== scope: tiddlers ===");
			if(!$tw.boot.wikiTiddlersPath) {
				return shared.errorResult("No wiki tiddlers path available. Cannot reload from filesystem.");
			}
			var resolvedWikiPath = $tw.boot.wikiTiddlersPath;
			// Effective retain: the outer config does not always carry the
			// flag in an includeWikis setup, so walk the include tree.
			var outerBase = path.resolve($tw.boot.wikiPath || ".");
			var effectiveRetain = wikiInfoHasRetain($tw.boot.wikiInfo, outerBase);
			var added = 0, updated = 0, skippedSystem = 0, unchanged = 0;
			var diskTiddlers = Object.create(null);
			var diskFileInfo = Object.create(null);
			// Texts captured for in-call rename detection. Pair added/deleted
			// titles whose `text` field matches exactly: that case is a
			// rename (most often via bash mv plus reload).
			var addedTexts = Object.create(null);
			var deletedTexts = Object.create(null);
			// Activate listener-suppression for this reload's own touches.
			var ownedTitles = Object.create(null);
			reloadOwnedTitles = ownedTitles;
			$tw.utils.each($tw.loadTiddlersFromPath(resolvedWikiPath), function(tiddlerFile) {
				$tw.utils.each(tiddlerFile.tiddlers, function(tiddlerFields) {
					var title = tiddlerFields.title;
					if(!title) return;
					diskTiddlers[title] = tiddlerFields;
					if(tiddlerFile.filepath) {
						diskFileInfo[title] = {
							filepath: tiddlerFile.filepath,
							type: tiddlerFile.type,
							hasMetaFile: tiddlerFile.hasMetaFile,
							isEditableFile: effectiveRetain || tiddlerFile.isEditableFile || tiddlerFile.filepath.indexOf($tw.boot.wikiTiddlersPath) !== 0
						};
						// Stamp originalpath like boot.js does. Core's
						// generateTiddlerFilepath reuses an existing on-disk
						// location ONLY via fileInfo.originalpath (filepath just
						// feeds the uniquifier), so a boot.files entry without it
						// makes the next save regenerate a root-level path from
						// the title -- relocating subdirectory .tid files.
						if(diskFileInfo[title].isEditableFile) {
							diskFileInfo[title].originalpath = path.relative($tw.boot.wikiTiddlersPath,tiddlerFile.filepath);
						}
					}
				});
			});
			for(var title in diskTiddlers) {
				// Refresh boot.files unconditionally -- system tiddlers (`$:/`)
				// still get their on-disk location tracked even though we skip
				// adding them to the wiki below. Without this, a system tiddler
				// file on disk + boot.files entry empty leaves TW core's syncer
				// to uniquify (`_1`) on the next save.
				if(diskFileInfo[title]) {
					$tw.boot.files[title] = diskFileInfo[title];
				}
				if(title.indexOf("$:/") === 0) {
					skippedSystem++;
					continue;
				}
				var tiddlerFields = diskTiddlers[title];
				var existing = $tw.wiki.getTiddler(title);
				if(existing) {
					var changed = false;
					var newTiddler = new $tw.Tiddler(tiddlerFields);
					var existingFields = existing.getFieldStrings();
					var newFields = newTiddler.getFieldStrings();
					if(Object.keys(existingFields).length !== Object.keys(newFields).length) {
						changed = true;
					} else {
						for(var field in newFields) {
							if(existingFields[field] !== newFields[field]) {
								changed = true;
								break;
							}
						}
					}
					if(changed) {
						ownedTitles[title] = true;
						addToWikiSilently(tiddlerFields);
						updated++;
					} else {
						unchanged++;
					}
				} else {
					ownedTitles[title] = true;
					addToWikiSilently(tiddlerFields);
					addedTexts[title] = tiddlerFields.text || "";
					added++;
				}
			}
			var deleted = 0;
			var allTitles = $tw.wiki.allTitles();
			for(var ti = 0; ti < allTitles.length; ti++) {
				var t = allTitles[ti];
				if($tw.boot.files[t] && $tw.boot.files[t].filepath) {
					var filePath = $tw.boot.files[t].filepath;
					if(filePath.indexOf(resolvedWikiPath) === 0 && !diskTiddlers[t]) {
						var existing = $tw.wiki.getTiddler(t);
						deletedTexts[t] = (existing && existing.fields.text) || "";
						ownedTitles[t] = true;
						$tw.wiki.deleteTiddler(t);
						delete $tw.boot.files[t];
						deleted++;
					}
				}
			}
			// Pair add/delete titles with identical text into renames. Each
			// pair represents ONE physical disk file, so decrement the raw
			// add/delete counters: a rename is counted in `renamed` only,
			// not in both `added` and `deleted`.
			var renames = [];
			for(var delTitle in deletedTexts) {
				for(var addTitle in addedTexts) {
					if(deletedTexts[delTitle] === addedTexts[addTitle]) {
						renames.push({from: delTitle, to: addTitle});
						delete addedTexts[addTitle];
						delete deletedTexts[delTitle];
						added--;
						deleted--;
						break;
					}
				}
			}
			// Rebuild $:/config/OriginalTiddlerPaths from $tw.boot.files when
			// any wiki in the includeWikis tree sets retain-original-tiddler-path.
			// When none do, leave OTP alone: it may still hold edge-case entries
			// from tiddlywiki.files imports that the boot-time generator created
			// independently of this flag.
			var otpRefreshed = false, otpSkipped = false, otpCount = 0;
			if(effectiveRetain) {
				var otpOutput = {};
				for(var btitle in $tw.boot.files) {
					var bfi = $tw.boot.files[btitle];
					if(bfi && bfi.isEditableFile && bfi.filepath) {
						var rel = path.relative($tw.boot.wikiTiddlersPath, bfi.filepath);
						otpOutput[btitle] = (path.sep === "/") ? rel : rel.split(path.sep).join("/");
						otpCount++;
					}
				}
				if(otpCount > 0) {
					addToWikiSilently({title: "$:/config/OriginalTiddlerPaths", type: "application/json", text: JSON.stringify(otpOutput)});
				}
				otpRefreshed = true;
			} else {
				otpSkipped = true;
			}
			// Disk-side diff summary. Renames are counted separately from
			// added/deleted so the row sums match the disk-tiddler total.
			var diskTotal = added + updated + unchanged + skippedSystem + deleted + renames.length;
			messages.push("Source: " + resolvedWikiPath);
			messages.push("Disk tiddlers: " + diskTotal + " (added: " + added + ", updated: " + updated + ", unchanged: " + unchanged + ", deleted: " + deleted + ", renamed: " + renames.length + ")");
			if(skippedSystem > 0) {
				messages.push("System tiddlers on disk: " + skippedSystem + " (left untouched by design)");
			}
			if(renames.length > 0) {
				for(var ri = 0; ri < renames.length; ri++) {
					messages.push("  ~ " + renames[ri].from + " -> " + renames[ri].to + " (rename: text identical)");
				}
			}
			if(otpRefreshed) {
				messages.push("OTP: refreshed (" + otpCount + " entries)");
			} else if(otpSkipped) {
				messages.push("OTP: skipped (retain-original-tiddler-path off)");
			}
			// Report changes since last reload via the event-driven change log.
			var logTitles = Object.keys(changeLog);
			if(logTitles.length > 0) {
				var logAdded = 0, logUpdated = 0, logDeleted = 0;
				var logLines = [];
				logTitles.sort();
				for(var li = 0; li < logTitles.length; li++) {
					var lt = logTitles[li];
					var action = changeLog[lt];
					if(action === "added") { logAdded++; logLines.push("  + " + lt + " (added)"); }
					else if(action === "updated") { logUpdated++; logLines.push("  ~ " + lt + " (updated)"); }
					else if(action === "deleted") { logDeleted++; logLines.push("  - " + lt + " (deleted)"); }
				}
				messages.push("\nChange log: " + (logAdded + logUpdated + logDeleted) + " changes since last reload (" + logAdded + " added, " + logUpdated + " updated, " + logDeleted + " deleted)");
				messages.push(logLines.join("\n"));
				changeLog = {};
			} else if(changeLogActive) {
				messages.push("\nChange log: no changes since last reload");
			} else {
				messages.push("\nChange log: empty (first reload after server start; future calls will diff from here)");
			}
			startChangeLog();
			// Release listener-suppression once the change events from this
			// reload's own touches have fired. nextTick fires before
			// setTimeout(0), so the listener sees `reloadOwnedTitles` set and
			// skips those titles; the timer then clears the pointer (but
			// only if a newer reload has not already replaced it).
			setTimeout(function() {
				if(reloadOwnedTitles === ownedTitles) {
					reloadOwnedTitles = null;
				}
			}, 0);
		}

		// Reload shadow tiddlers from plugins
		if(scope === "shadows" || scope === "all") {
			if(dualScope) messages.push("\n=== scope: shadows ===");
			else messages.push("");  // separator when shadows-only
			try {
				var shadowsBefore = $tw.wiki.allShadowTitles().length;
				var results = $tw.wiki.readPluginInfo();
				var modified = results.modifiedPlugins || [];
				$tw.wiki.registerPluginTiddlers(null);
				$tw.wiki.unpackPluginTiddlers();
				var shadowsAfter = $tw.wiki.allShadowTitles().length;
				messages.push("Shadow tiddlers: " + shadowsBefore + " -> " + shadowsAfter + " (re-registered from in-memory plugin JSON; plugin folders NOT re-read)");
				if(modified.length > 0) {
					messages.push("Modified plugins: " + modified.join(", "));
				} else {
					messages.push("No plugin changes detected");
				}
			} catch(e) {
				messages.push("Shadow reload error: " + e.message);
			}
		}

		return shared.textResult(messages.join("\n"));
	},

	"save_wiki_folder": function(args) {
		var denied = shared.checkWritable("save_wiki_folder");
		if(denied) return denied;
		var checkPathAllowed = shared.getCheckPathAllowed();
		var outputPath = path.resolve(args.path);
		var pathDenied = checkPathAllowed(outputPath);
		if(pathDenied) return pathDenied;
		var tiddlerFilter = args.filter || "[all[tiddlers]]";
		var explodePlugins = (args.explodePlugins === "no") ? "no" : "yes";
		try {
			var commander = new $tw.Commander(
				["--savewikifolder", outputPath, "filter=" + tiddlerFilter, "explodePlugins=" + explodePlugins],
				function(err) {
					if(err) {
						process.stderr.write("[tw-mcp] savewikifolder error: " + err + "\n");
					}
				},
				$tw.wiki
			);
			commander.execute();
			return shared.textResult("Wiki folder saved to: " + outputPath);
		} catch(e) {
			return shared.errorResult("Failed to save wiki folder: " + e.message);
		}
	},

	"upload_file": function(args) {
		var denied = shared.checkWritable("upload_file");
		if(denied) return denied;
		var titleErr = shared.checkTitle(args.title, "upload_file");
		if(titleErr) return titleErr;
		if(typeof args.data !== "string") {
			return shared.errorResult("upload_file: data must be a base64-encoded string");
		}
		if(args.data.length > MAX_UPLOAD_BASE64_LENGTH) {
			return shared.errorResult("upload_file: data exceeds " + MAX_UPLOAD_BYTES + " bytes (50 MB)");
		}
		var checkPathAllowed = shared.getCheckPathAllowed();
		var filename = args.filename;
		if(filename.indexOf("/") !== -1 || filename.indexOf("\\") !== -1 || filename.indexOf("..") !== -1) {
			return shared.errorResult("Invalid filename: must not contain path separators or '..'");
		}
		var wikiPath = $tw.boot.wikiPath;
		if(!wikiPath) {
			return shared.errorResult("No wiki path available");
		}
		var filesDir = path.resolve(wikiPath, "files");
		if(args.subfolder) {
			var subfolder = args.subfolder;
			if(subfolder.indexOf("..") !== -1) {
				return shared.errorResult("Invalid subfolder: must not contain '..'");
			}
			filesDir = path.resolve(filesDir, subfolder);
		}
		var targetPath = path.resolve(filesDir, filename);
		var pathDenied = checkPathAllowed(targetPath);
		if(pathDenied) return pathDenied;
		try {
			var buffer = Buffer.from(args.data, "base64");
			$tw.utils.createDirectory(filesDir);
			fs.writeFileSync(targetPath, buffer);
		} catch(e) {
			return shared.errorResult("Failed to write file: " + e.message);
		}
		var title = args.title || filename;
		var canonicalUri = "files/" + (args.subfolder ? args.subfolder + "/" : "") + filename;
		var creationFields = $tw.wiki.getCreationFields();
		var modificationFields = $tw.wiki.getModificationFields();
		var tiddlerFields = {
			title: title,
			type: args.type,
			_canonical_uri: canonicalUri
		};
		if(args.tags) {
			tiddlerFields.tags = args.tags;
		}
		var tiddler = new $tw.Tiddler(creationFields, tiddlerFields, modificationFields);
		addToWikiSilently(tiddler.fields);
		try {
			var tiddlerFileInfo = $tw.utils.generateTiddlerFileInfo(tiddler, {
				directory: $tw.boot.wikiTiddlersPath,
				wiki: $tw.wiki,
				fileInfo: {}
			});
			$tw.utils.saveTiddlerToFileSync(tiddler, tiddlerFileInfo);
			$tw.boot.files[title] = tiddlerFileInfo;
		} catch(e) {
			return shared.errorResult("File saved but failed to write .tid tiddler: " + e.message);
		}
		return shared.textResult("File uploaded: " + targetPath + "\nTiddler created: " + tiddlerFileInfo.filepath + " (_canonical_uri: " + canonicalUri + ")");
	},

	"build_wiki": function(args) {
		var denied = shared.checkWritable("build_wiki");
		if(denied) return denied;
		var checkPathAllowed = shared.getCheckPathAllowed();
		var outputFile = path.resolve(args.output);
		var pathDenied = checkPathAllowed(outputFile);
		if(pathDenied) return pathDenied;
		var template = args.template || "$:/core/save/all";
		try {
			var text = $tw.wiki.renderTiddler("text/plain", template);
			$tw.utils.createFileDirectories(outputFile);
			fs.writeFileSync(outputFile, text, "utf8");
			return shared.textResult("Wiki built: " + outputFile);
		} catch(e) {
			return shared.errorResult("Failed to build wiki: " + e.message);
		}
	}
};

// MCP tool definition — advertised via mcp-handlers getToolDefinitions();
// write:true marks tools hidden in readonly mode.
module.exports["reload_tiddlers"].definition = {
	"description": "Re-read tiddlers from disk; reports diff vs last call (first call may show large initial set). scope='shadows': refreshes non-JS plugin subtiddlers (doc/wikitext/CSS) — does NOT re-execute plugin JS. For JS in tw-mcp plugin use reload_mcp_modules. Refreshes $:/config/OriginalTiddlerPaths when retain-original-tiddler-path is set.",
	"inputSchema": {
		"type": "object",
		"properties": {
			"scope": {
				"type": "string",
				"enum": [
					"tiddlers",
					"shadows",
					"all"
				],
				"default": "tiddlers",
				"description": "tiddlers = edition tiddlers on disk (default). shadows = re-register plugins and re-unpack shadow tiddlers from in-memory plugin JSON (does NOT re-read plugin folders from disk). all = both."
			}
		},
		"required": []
	}
};

// MCP tool definition — advertised via mcp-handlers getToolDefinitions();
// write:true marks tools hidden in readonly mode.
module.exports["save_wiki_folder"].definition = {
	"description": "Export wiki to folder. filter selects tiddlers (default '[all[tiddlers]]'). explodePlugins='yes' (default): plugins as exploded subtiddler folders; 'no': single .json bundles. Path gated by allowed-paths.",
	"inputSchema": {
		"type": "object",
		"properties": {
			"path": {
				"type": "string",
				"description": "Output directory"
			},
			"filter": {
				"type": "string",
				"default": "[all[tiddlers]]"
			},
			"explodePlugins": {
				"type": "string",
				"enum": [
					"yes",
					"no"
				],
				"default": "yes"
			}
		},
		"required": [
			"path"
		]
	},
	"write": true
};

// MCP tool definition — advertised via mcp-handlers getToolDefinitions();
// write:true marks tools hidden in readonly mode.
module.exports["build_wiki"].definition = {
	"description": "Render wiki as single HTML. Silently overwrites output, creates parent dirs. template = renderable tiddler (default '$:/core/save/all'); invalid template → empty output, not error. Verify result.",
	"inputSchema": {
		"type": "object",
		"properties": {
			"output": {
				"type": "string",
				"description": "Output file path"
			},
			"template": {
				"type": "string",
				"default": "$:/core/save/all"
			}
		},
		"required": [
			"output"
		]
	},
	"write": true
};

// MCP tool definition — advertised via mcp-handlers getToolDefinitions();
// write:true marks tools hidden in readonly mode.
module.exports["upload_file"].definition = {
	"description": "Upload base64 file to files/, create canonical tiddler. tags = TW-format STRING (e.g. 'foo [[bar baz]]'), NOT array. Writes binary file + .tid sidecar with _canonical_uri.",
	"inputSchema": {
		"type": "object",
		"properties": {
			"filename": {
				"type": "string",
				"description": "Filename (no path separators)"
			},
			"data": {
				"type": "string",
				"description": "Base64 content"
			},
			"type": {
				"type": "string",
				"description": "MIME type"
			},
			"title": {
				"type": "string",
				"maxLength": 1024,
				"description": "Tiddler title (max 1024 chars; defaults to filename)"
			},
			"tags": {
				"type": "string"
			},
			"subfolder": {
				"type": "string",
				"description": "Subfolder in files/"
			}
		},
		"required": [
			"filename",
			"data",
			"type"
		]
	},
	"write": true
};
","type":"application/javascript","module-type":"mcp-handler"},"$:/core/modules/commands/inspect/handlers/html-import.js":{"title":"$:/core/modules/commands/inspect/handlers/html-import.js","text":"/*\
title: $:/core/modules/commands/inspect/handlers/html-import.js
type: application/javascript
module-type: mcp-handler

HTML single-file wiki import handler for MCP server.
Loads tiddlers from an HTML file, analyzes structure, and provides
deferred extraction to disk with FileSystemPaths configuration.

\*/

"use strict";

var fs = $tw.node ? require("fs") : null,
	path = $tw.node ? require("path") : null;

var shared = require("$:/core/modules/commands/inspect/handlers/shared.js");

var TIDDLERS_TO_IGNORE = [
	"$:/boot/boot.css",
	"$:/boot/boot.js",
	"$:/boot/bootprefix.js",
	"$:/core",
	"$:/core-server",
	"$:/library/sjcl.js",
	"$:/temp/info-plugin"
];

var MIN_GROUP_COUNT = 3;

// import_html_wiki accepts paths from anywhere on disk by design (the user
// typically points it at a downloaded `index.html`), so we cannot gate it on
// `allowedPaths` like upload_file does. As a defence-in-depth, refuse any
// resolved path whose directory or file segments start with `.` -- those are
// conventional homes for secrets (.ssh, .aws, .config, .npmrc, .env, ...)
// with no legitimate role as a single-file wiki source.
function hasDotComponent(p) {
	var parts = p.split(/[\/\\]/);
	for(var i = 0; i < parts.length; i++) {
		if(parts[i].length > 0 && parts[i].charAt(0) === ".") return true;
	}
	return false;
}

// Plugins/themes/languages loaded by the running wiki via tiddlywiki.info
// must NOT be treated as custom plugins from the imported HTML, and must
// NOT be written to disk by extract (they will load from the local plugin
// path again on the next boot).
function bootedPluginTitleSet() {
	var info = $tw.boot.wikiInfo || {};
	var set = {};
	(info.plugins || []).forEach(function(n) { set["$:/plugins/" + n] = true; });
	(info.themes || []).forEach(function(n) { set["$:/themes/" + n] = true; });
	(info.languages || []).forEach(function(n) { set["$:/languages/" + n] = true; });
	return set;
}

// Trim leading/trailing whitespace and trailing dots from each path component.
// Windows silently strips trailing whitespace/dots from path components when
// passed through the Win32 API, so files written with such names become
// unreachable through normal tools (they require the \\?\ prefix to access).
function sanitisePathComponents(filepath) {
	var parts = filepath.split(path.sep);
	return parts.map(function(part, idx) {
		if(part === "") return part;
		if(idx === 0 && /^[A-Za-z]:$/.test(part)) return part;
		var cleaned = part.replace(/^\s+/, "").replace(/[\s.]+$/, "");
		return cleaned || "_unnamed_";
	}).join(path.sep);
}

// --- Plugin detection (adapted from savewikifolder.js) ---

function findPluginInLibrary(title) {
	var parts = title.split("/"),
		pluginPath, type, name;
	if(parts[0] === "$:") {
		if(parts[1] === "languages" && parts.length === 3) {
			pluginPath = "languages" + path.sep + parts[2];
			type = parts[1];
			name = parts[2];
		} else if((parts[1] === "plugins" || parts[1] === "themes") && parts.length === 4) {
			pluginPath = parts[1] + path.sep + parts[2] + path.sep + parts[3];
			type = parts[1];
			name = parts[2] + "/" + parts[3];
		}
	}
	if(pluginPath && type && name) {
		pluginPath = path.resolve($tw.boot.bootPath, "..", pluginPath);
		if(fs.existsSync(pluginPath)) {
			return { pluginPath: pluginPath, type: type, name: name };
		}
	}
	return false;
}

// --- Heuristic analysis ---

function analyzeForFileSystemPaths(tiddlers) {
	var tagCounts = {};
	var prefixCounts = {};
	for(var i = 0; i < tiddlers.length; i++) {
		var t = tiddlers[i];
		// Count tags
		var tags = $tw.utils.parseStringArray(t.tags || "");
		for(var ti = 0; ti < tags.length; ti++) {
			var tag = tags[ti];
			if(tag.indexOf("$:/") !== 0) {
				tagCounts[tag] = (tagCounts[tag] || 0) + 1;
			}
		}
		// Count title prefixes (first segment before /)
		var slashIdx = t.title.indexOf("/");
		if(slashIdx > 0) {
			var prefix = t.title.substring(0, slashIdx + 1);
			prefixCounts[prefix] = (prefixCounts[prefix] || 0) + 1;
		}
	}
	// Build proposed rules
	var rules = [];
	var ruleDescriptions = [];
	// System tiddlers
	rules.push("[is[system]removeprefix[$:/]addprefix[_system/]]");
	ruleDescriptions.push("System tiddlers ($:/) → _system/ subfolder");
	// Tags with enough tiddlers
	var sortedTags = Object.keys(tagCounts)
		.filter(function(t) { return tagCounts[t] >= MIN_GROUP_COUNT; })
		.sort(function(a, b) { return tagCounts[b] - tagCounts[a]; });
	for(var si = 0; si < sortedTags.length; si++) {
		var tag = sortedTags[si];
		var folder = tag.toLowerCase()
			.replace(/\s+/g, "-")
			.replace(/[^a-z0-9\-]+/g, "_")
			.replace(/^[-_]+|[-_]+$/g, "");
		rules.push("[tag[" + tag + "]addprefix[" + folder + "/]]");
		ruleDescriptions.push(tagCounts[tag] + " tiddlers tagged '" + tag + "' → " + folder + "/ subfolder");
	}
	// Title prefixes with enough tiddlers
	var sortedPrefixes = Object.keys(prefixCounts)
		.filter(function(p) { return prefixCounts[p] >= MIN_GROUP_COUNT; })
		.sort(function(a, b) { return prefixCounts[b] - prefixCounts[a]; });
	for(var pi = 0; pi < sortedPrefixes.length; pi++) {
		var prefix = sortedPrefixes[pi];
		rules.push("[prefix[" + prefix + "]]");
		ruleDescriptions.push(prefixCounts[prefix] + " tiddlers with title prefix '" + prefix + "' → keep namespace as subfolder");
	}
	return {
		tagCounts: tagCounts,
		prefixCounts: prefixCounts,
		proposedRules: rules,
		ruleDescriptions: ruleDescriptions,
		proposedText: rules.join("\n")
	};
}

// --- Import handler: load HTML, analyze, stage in memory ---

function importHandler(args) {
	var writeCheck = shared.checkWritable("import_html_wiki");
	if(writeCheck) return writeCheck;
	if(!args.path) {
		return shared.errorResult("Missing required argument 'path' (path to single-file HTML wiki).");
	}
	var filePath = path.resolve(args.path);
	// Reject hidden-directory / dot-file paths BEFORE the existence check so
	// an attacker can't probe for which dot-files are present (existence vs
	// refusal would otherwise be distinguishable).
	if(hasDotComponent(filePath)) {
		return shared.errorResult("Refused: path contains a hidden (dot-prefixed) directory or file. (" + filePath + ")");
	}
	if(!fs.existsSync(filePath)) {
		return shared.errorResult("File not found: " + filePath);
	}
	var wiki = $tw.wiki;
	// Refuse if a pending import is already staged
	var existing = wiki.getTiddler("$:/temp/mcp/html-import");
	if(existing && existing.fields.status === "pending") {
		return shared.errorResult("An HTML import is already pending (source: " + existing.fields["source-file"] + "). Call extract_html_wiki to commit it, or delete $:/temp/mcp/html-import to discard.");
	}
	// Refuse if the wiki folder is already populated
	if($tw.boot.wikiTiddlersPath && fs.existsSync($tw.boot.wikiTiddlersPath)) {
		var existingFiles = fs.readdirSync($tw.boot.wikiTiddlersPath);
		var hasTidFiles = existingFiles.some(function(f) { return f.endsWith(".tid"); });
		if(hasTidFiles && wiki.tiddlerExists("$:/config/FileSystemPaths")) {
			return shared.errorResult("Wiki already has extracted tiddlers and FileSystemPaths. Run import against an empty wiki folder.");
		}
	}
	// Ensure tiddlers directory exists
	var wikiPath = $tw.boot.wikiPath;
	var tiddlersDir = path.resolve(wikiPath, "tiddlers");
	if(!fs.existsSync(tiddlersDir)) {
		$tw.utils.createDirectory(tiddlersDir);
	}
	if(!$tw.boot.wikiTiddlersPath) {
		$tw.boot.wikiTiddlersPath = tiddlersDir;
	}
	// Ensure tiddlywiki.info exists
	var infoPath = path.resolve(wikiPath, "tiddlywiki.info");
	var wikiInfo;
	if(fs.existsSync(infoPath)) {
		wikiInfo = $tw.utils.parseJSONSafe(fs.readFileSync(infoPath, "utf8"), {});
	} else {
		wikiInfo = {};
	}
	// Load tiddlers from HTML
	var loaded = $tw.loadTiddlersFromPath(filePath);
	// Classify tiddlers
	var bootedPlugins = bootedPluginTitleSet();
	var contentTiddlers = [];
	var systemTiddlers = [];
	var libraryPlugins = [];
	var customPlugins = [];
	var ignoredCount = 0;
	$tw.utils.each(loaded, function(tiddlerInfo) {
		$tw.utils.each(tiddlerInfo.tiddlers, function(fields) {
			if(!fields.title) return;
			// Skip boot/core tiddlers
			if(TIDDLERS_TO_IGNORE.indexOf(fields.title) !== -1) {
				ignoredCount++;
				return;
			}
			// Check if it's a plugin
			var type = fields.type,
				pluginType = fields["plugin-type"];
			if(type === "application/json" && pluginType) {
				// Plugin already loaded by the running tiddlywiki.info — skip; the
				// local plugin path will load it again on next boot.
				if(bootedPlugins[fields.title]) {
					ignoredCount++;
					return;
				}
				var libraryInfo = findPluginInLibrary(fields.title);
				if(libraryInfo) {
					libraryPlugins.push(libraryInfo);
					return;
				}
				customPlugins.push(fields);
				return;
			}
			// System vs content
			if(fields.title.indexOf("$:/") === 0) {
				systemTiddlers.push(fields);
			} else {
				contentTiddlers.push(fields);
			}
		});
	});
	// Update tiddlywiki.info with library plugins
	var infoChanged = false;
	for(var li = 0; li < libraryPlugins.length; li++) {
		var lp = libraryPlugins[li];
		if(!wikiInfo[lp.type]) {
			wikiInfo[lp.type] = [];
		}
		if(wikiInfo[lp.type].indexOf(lp.name) === -1) {
			wikiInfo[lp.type].push(lp.name);
			infoChanged = true;
		}
	}
	if(infoChanged || !fs.existsSync(infoPath)) {
		fs.writeFileSync(infoPath, JSON.stringify(wikiInfo, null, 4), "utf8");
	}
	// Import all content + system + custom-plugin tiddlers into memory
	var allTiddlers = contentTiddlers.concat(systemTiddlers).concat(customPlugins);
	for(var ai = 0; ai < allTiddlers.length; ai++) {
		wiki.importTiddler(new $tw.Tiddler(allTiddlers[ai]));
	}
	// Reset syncer baseline so imported tiddlers are not seen as dirty
	if($tw.syncer) {
		$tw.syncer.readTiddlerInfo();
	}
	// Analyze for FileSystemPaths
	var analysis = analyzeForFileSystemPaths(contentTiddlers);
	// Build explanation
	var explanation = [
		"## $:/config/FileSystemPaths",
		"",
		"This TiddlyWiki configuration controls how tiddlers are organized into subdirectories when saved as .tid files.",
		"Each line is a filter expression. Tiddlers are tested against each filter in order — the first match determines the subfolder.",
		"If no filter matches, the tiddler title is used as the filename in the tiddlers/ root.",
		"",
		"Full documentation: https://tiddlywiki.com/#Customising%20Tiddler%20File%20Naming",
		"",
		"## Proposed rules",
		""
	];
	var maxExamples = 10;
	var ruleCount = analysis.ruleDescriptions.length;
	var showCount = Math.min(ruleCount, maxExamples);
	for(var ri = 0; ri < showCount; ri++) {
		explanation.push("- " + analysis.ruleDescriptions[ri]);
		explanation.push("  `" + analysis.proposedRules[ri] + "`");
	}
	if(ruleCount > maxExamples) {
		explanation.push("- ... and " + (ruleCount - maxExamples) + " more rules");
		explanation.push("");
		explanation.push("See [[Import — Proposed Folder Structure]] for the full list. You can review it in the browser.");
	}
	explanation.push("");
	explanation.push("## Tiddler counts");
	explanation.push("- Content tiddlers: " + contentTiddlers.length);
	explanation.push("- System tiddlers: " + systemTiddlers.length);
	explanation.push("- Library plugins (added to tiddlywiki.info): " + libraryPlugins.length);
	explanation.push("- Custom plugins (kept as single .tid files): " + customPlugins.length);
	explanation.push("- Ignored (boot/core): " + ignoredCount);
	var totalTags = Object.keys(analysis.tagCounts).length;
	var totalPrefixes = Object.keys(analysis.prefixCounts).length;
	if(totalTags > 0 || totalPrefixes > 0) {
		explanation.push("");
		explanation.push("## Summary");
		explanation.push("- " + totalTags + " unique tags found (" + analysis.proposedRules.filter(function(r) { return r.indexOf("[tag[") !== -1; }).length + " with " + MIN_GROUP_COUNT + "+ tiddlers → proposed as folders)");
		explanation.push("- " + totalPrefixes + " title prefixes found (" + analysis.proposedRules.filter(function(r) { return r.indexOf("[prefix[") !== -1; }).length + " with " + MIN_GROUP_COUNT + "+ tiddlers → proposed as folders)");
	}
	// Store analysis tiddler
	var analysisTiddler = new $tw.Tiddler({
		title: "$:/temp/mcp/html-import",
		type: "text/vnd.tiddlywiki",
		text: explanation.join("\n"),
		status: "pending",
		"source-file": filePath,
		"content-count": String(contentTiddlers.length),
		"system-count": String(systemTiddlers.length),
		"library-plugin-count": String(libraryPlugins.length),
		"custom-plugin-count": String(customPlugins.length),
		"proposed-filesystem-paths": analysis.proposedText
	});
	wiki.addTiddler(analysisTiddler);
	// Create a visible tiddler with the full proposed rules (browsable in the wiki)
	var fullRulesLines = [
		"! Proposed Folder Structure",
		"",
		"These rules will be used by `$:/config/FileSystemPaths` to organize your tiddlers into subdirectories.",
		"Each tiddler is tested against the rules in order — the first match determines the folder.",
		"",
		"!! Rules (" + ruleCount + ")",
		""
	];
	for(var fri = 0; fri < analysis.ruleDescriptions.length; fri++) {
		fullRulesLines.push("# " + analysis.ruleDescriptions[fri]);
		fullRulesLines.push("#* `" + analysis.proposedRules[fri] + "`");
	}
	fullRulesLines.push("");
	fullRulesLines.push("!! What to do");
	fullRulesLines.push("");
	fullRulesLines.push("# Review the rules above");
	fullRulesLines.push("# Edit [[$:/config/FileSystemPaths]] in the browser if you want to change anything");
	fullRulesLines.push("# Tell the AI assistant to proceed with extraction");
	fullRulesLines.push("");
	fullRulesLines.push("[[Full documentation|https://tiddlywiki.com/#Customising%20Tiddler%20File%20Naming]]");
	var now = $tw.utils.stringifyDate(new Date());
	wiki.addTiddler(new $tw.Tiddler({
		title: "Import — Proposed Folder Structure",
		text: fullRulesLines.join("\n"),
		tags: "Import",
		modified: now,
		created: now
	}));
	// Create $:/config/FileSystemPaths so user can edit it in the browser before extraction
	wiki.addTiddler(new $tw.Tiddler({
		title: "$:/config/FileSystemPaths",
		text: analysis.proposedText,
		modified: now,
		created: now
	}));
	// Set as default tiddler so it opens on startup in the browser
	wiki.addTiddler(new $tw.Tiddler({
		title: "$:/DefaultTiddlers",
		text: "[[Import — Proposed Folder Structure]]"
	}));
	var summary = [
		"Loaded " + filePath,
		"  content: " + contentTiddlers.length + " · system: " + systemTiddlers.length + " · library plugins: " + libraryPlugins.length + " · custom plugins: " + customPlugins.length + " · ignored: " + ignoredCount,
		"  " + analysis.proposedRules.length + " FileSystemPaths rules proposed.",
		"",
		"Nothing written to disk yet. Next steps:",
		"  1. Read $:/temp/mcp/html-import for the analysis summary.",
		"  2. Show the user the proposed folder structure (also visible in the browser as 'Import — Proposed Folder Structure').",
		"  3. Let the user edit $:/config/FileSystemPaths in the browser if they want changes.",
		"  4. When approved, call extract_html_wiki() to commit the .tid files to disk.",
		"  5. Restart the server once after extraction so any new library plugins activate."
	].join("\n");
	return shared.textResult(summary);
}

// --- MCP tool handler: extract to disk ---

function extractHandler(args) {
	var writeCheck = shared.checkWritable("extract_html_wiki");
	if(writeCheck) return writeCheck;
	var analysisTiddler = $tw.wiki.getTiddler("$:/temp/mcp/html-import");
	if(!analysisTiddler) {
		return shared.errorResult("No pending HTML import found. Call import_html_wiki(path) first to stage a single-file wiki.");
	}
	if(analysisTiddler.fields.status === "extracted") {
		return shared.errorResult("Tiddlers have already been extracted to disk.");
	}
	// Determine FileSystemPaths: args override > user-edited tiddler > proposed
	var fileSystemPathsText = args.fileSystemPaths
		|| $tw.wiki.getTiddlerText("$:/config/FileSystemPaths", "")
		|| analysisTiddler.fields["proposed-filesystem-paths"];
	if(!fileSystemPathsText) {
		return shared.errorResult("No FileSystemPaths rules available.");
	}
	// Update the FileSystemPaths config tiddler (in case args override was used).
	// Use storeTiddler: the explicit save loop below writes this tiddler to disk
	// itself, so the syncer must not also queue an async save for it.
	shared.addToWikiSilently(new $tw.Tiddler({
		title: "$:/config/FileSystemPaths",
		text: fileSystemPathsText
	}).fields);
	// Parse path filters. addToWikiSilently above just synced fileSystemPathsText
	// into $:/config/FileSystemPaths, so loadFspFseFilters reads back the same
	// text. filterBlank:true preserves the previous behaviour of dropping
	// whitespace-only rule lines.
	var filters = shared.loadFspFseFilters({ filterBlank: true });
	var pathFilters = filters.pathFilters;
	var extFilters = filters.extFilters;
	var tiddlersDir = $tw.boot.wikiTiddlersPath;
	if(!tiddlersDir) {
		return shared.errorResult("No wiki tiddlers path available.");
	}
	// Get tiddlers to extract — regular content + system + custom plugin tiddlers
	// (kept as single tiddlers, not exploded). Library plugins live in tiddlywiki.info
	// and are not in the regular tiddler space, so they're naturally excluded.
	var allTitles = $tw.wiki.filterTiddlers(
		"[all[tiddlers]!has[plugin-type]]" +
		" [all[tiddlers]plugin-type[plugin]]" +
		" -[prefix[$:/state/popup/]]" +
		" -[prefix[$:/temp/]]" +
		" -[prefix[$:/HistoryList]]" +
		" -[[$:/boot/boot.css]]" +
		" -[[$:/boot/boot.js]]" +
		" -[[$:/boot/bootprefix.js]]" +
		" -[[$:/library/sjcl.js]]" +
		" -[is[system]type[application/javascript]library[yes]]" +
		" -[status[pending]plugin-type[import]]"
	);
	var checkPathAllowed = shared.getCheckPathAllowed();
	var bootedPlugins = bootedPluginTitleSet();
	var filesWritten = 0;
	var errors = [];
	var directorySummary = {};
	for(var i = 0; i < allTitles.length; i++) {
		var title = allTitles[i];
		// Skip tiddlers that already have fileInfo (already on disk)
		if($tw.boot.files[title]) continue;
		// Skip plugins/themes/languages loaded by tiddlywiki.info — they live in
		// the local plugin path and must not be duplicated under tiddlers/.
		if(bootedPlugins[title]) continue;
		var tiddler = $tw.wiki.getTiddler(title);
		if(!tiddler) continue;
		try {
			var fileInfo = $tw.utils.generateTiddlerFileInfo(tiddler, {
				directory: tiddlersDir,
				pathFilters: pathFilters,
				extFilters: extFilters,
				wiki: $tw.wiki,
				fileInfo: {}
			});
			fileInfo.filepath = sanitisePathComponents(fileInfo.filepath);
			var pathDenied = checkPathAllowed(fileInfo.filepath);
			if(pathDenied) {
				errors.push(title + ": path denied");
				continue;
			}
			$tw.utils.saveTiddlerToFileSync(tiddler, fileInfo);
			$tw.boot.files[title] = fileInfo;
			filesWritten++;
			// Track directory for summary
			var relPath = path.relative(tiddlersDir, fileInfo.filepath);
			var dir = path.dirname(relPath);
			directorySummary[dir] = (directorySummary[dir] || 0) + 1;
		} catch(e) {
			errors.push(title + ": " + e.message);
		}
	}
	// Update analysis tiddler status
	$tw.wiki.addTiddler(new $tw.Tiddler(analysisTiddler, {
		status: "extracted",
		"files-written": String(filesWritten)
	}));
	// Build result
	var lines = ["Extracted " + filesWritten + " tiddlers to " + tiddlersDir];
	lines.push("");
	var dirs = Object.keys(directorySummary).sort();
	for(var di = 0; di < dirs.length; di++) {
		lines.push("  " + (dirs[di] === "." ? "(root)" : dirs[di] + "/") + " — " + directorySummary[dirs[di]] + " files");
	}
	if(errors.length > 0) {
		lines.push("");
		lines.push(errors.length + " errors:");
		for(var ei = 0; ei < errors.length; ei++) {
			lines.push("  " + errors[ei]);
		}
	}
	var result = lines.join("\n");
	console.error("\nhtml-import: " + result + "\n");
	return shared.textResult(result);
}

module.exports = {
	"import_html_wiki": importHandler,
	"extract_html_wiki": extractHandler
};

// MCP tool definition — advertised via mcp-handlers getToolDefinitions();
// write:true marks tools hidden in readonly mode.
module.exports["import_html_wiki"].definition = {
	"description": "Stage a single-file HTML wiki for import. Loads tiddlers from the file into memory, classifies them, proposes FileSystemPaths rules, and writes the staged analysis to $:/temp/mcp/html-import. Nothing is written to disk yet — call extract_html_wiki to commit. Refuses if the wiki folder is already populated or another import is already pending.",
	"inputSchema": {
		"type": "object",
		"properties": {
			"path": {
				"type": "string",
				"description": "Path to the .html single-file wiki to import. Paths with `.`-prefixed directory or filename segments (e.g. `.ssh/`, `.config/`, `.env`) are refused as a defence-in-depth against reading hidden config."
			}
		},
		"required": [
			"path"
		]
	},
	"write": true
};

// MCP tool definition — advertised via mcp-handlers getToolDefinitions();
// write:true marks tools hidden in readonly mode.
module.exports["extract_html_wiki"].definition = {
	"description": "Commit a previously staged HTML wiki import (see import_html_wiki) to disk as .tid files. Reads $:/config/FileSystemPaths from the wiki by default; the user can edit it in the browser before this call. Optionally override the rules via fileSystemPaths.",
	"inputSchema": {
		"type": "object",
		"properties": {
			"fileSystemPaths": {
				"type": "string",
				"description": "Approved FileSystemPaths rules (one filter per line). If omitted, reads $:/config/FileSystemPaths from the wiki."
			}
		},
		"required": []
	},
	"write": true
};
","type":"application/javascript","module-type":"mcp-handler"},"$:/core/modules/commands/mcp.js":{"title":"$:/core/modules/commands/mcp.js","text":"/*\
title: $:/core/modules/commands/mcp.js
type: application/javascript
module-type: command

MCP (Model Context Protocol) server for TiddlyWiki.
Exposes wiki tools to Claude CLI and other MCP clients via stdio.

Usage (readonly by default):
  tiddlywiki ./wiki --mcp [label=<name>] [allowed-paths=<paths>]
  tiddlywiki ./wiki --mcp rw [label=<name>] [allowed-paths=<paths>]
  tiddlywiki ./wiki --mcp rw listen [port=<n>] [host=<h>] [label=<name>] ...
  tiddlywiki ./wiki --mcp rw sse    [port=<n>] [host=<h>] [label=<name>] ...
  tiddlywiki ./wiki --mcp pear=<accountDir>   (serve a RUNNING Facets app)

Pear mode serves a running Facets (Pear) app instead of this process's wiki:
<accountDir> is a Facets account directory whose mcp.json discovery file
names the app's agent pipe. All other flags are ignored in pear mode; the
read/write mode follows the app's own mcp.flag. See mcp-pear.js.

Single-file wiki workflow (runtime tools):
  Start a normal --mcp rw listen server against an empty wiki folder, then
  call import_html_wiki(path) to stage an HTML wiki for review and
  extract_html_wiki() to commit it to disk.

When "listen" is specified, an HTTP server is started in the same process
before the MCP server, so browser edits and MCP tool calls share one $tw.wiki.
All --listen parameters (port, host, credentials, tls-*, etc.) are accepted.

When "sse" is specified, "listen" is implied AND the Server-Sent Events
endpoint at GET /events is enabled. Browsers that load this plugin will
receive per-tiddler change notifications instead of polling for the full
tiddler list every 60s — see $:/plugins/wikilabs/tw-mcp/sse/ for the
client-side adaptor and bootstrap.
If both "sse" and "listen" are given, sse wins (no error).

\*/

"use strict";

var startMCPServer = require("$:/core/modules/commands/inspect/mcp-lib.js").startMCPServer;
var Server = require("$:/core/modules/server/server.js").Server;

exports.info = {
	name: "mcp",
	synchronous: true
};

var Command = function(params, commander, callback) {
	this.params = params;
	this.commander = commander;
	this.callback = callback;
};

Command.prototype.execute = function() {
	var options = { readonly: true }; // readonly by default
	var listenMode = false;
	var sseMode = false;
	var listenParams = {};
	for(var i = 0; i < this.params.length; i++) {
		var param = this.params[i];
		if(param === "readonly") {
			options.readonly = true;
		} else if(param === "rw" || param === "readwrite") {
			options.readonly = false;
		} else if(param === "listen") {
			listenMode = true;
		} else if(param === "sse") {
			listenMode = true;
			sseMode = true;
		} else if(param.indexOf("pear=") === 0) {
			options.pearDir = param.slice("pear=".length);
		} else if(param.indexOf("allowed-paths=") === 0) {
			options.allowedPaths = param.slice("allowed-paths=".length).split(",");
		} else if(param.indexOf("label=") === 0) {
			options.label = param.slice("label=".length);
		} else if(param.indexOf("=") !== -1) {
			// Named parameter — forward to listen server if in listen mode
			var eq = param.indexOf("=");
			listenParams[param.slice(0, eq)] = param.slice(eq + 1);
		}
	}
	// Pear mode: the stdio front dials a running Facets app's pipe — no local
	// handlers, no HTTP, no primary/proxy machinery. Everything below is the
	// local-wiki path and does not apply.
	if(options.pearDir) {
		require("$:/core/modules/commands/inspect/mcp-pear.js").startPearMode(options);
		return null;
	}
	// Load the filesystem plugin if not already present (needed for disk persistence)
	if(!options.readonly && !$tw.wiki.getTiddler("$:/plugins/tiddlywiki/filesystem")) {
		$tw.loadPlugins(["tiddlywiki/filesystem"], $tw.config.pluginsPath, $tw.config.pluginsEnvVar);
		$tw.wiki.registerPluginTiddlers("plugin");
		$tw.wiki.unpackPluginTiddlers();
	}
	// Start HTTP server if listen mode is enabled
	if(listenMode) {
		var mcpLib = require("$:/core/modules/commands/inspect/mcp-lib.js");
		var discovery = mcpLib.readDiscoveryFile();
		if(discovery && discovery.listen) {
			console.error("Primary already serves HTTP — skipping local HTTP server");
		} else {
			if(!$tw.boot.wikiTiddlersPath) {
				$tw.utils.warning("Warning: Wiki folder '" + $tw.boot.wikiPath + "' does not exist or is missing a tiddlywiki.info file");
			}
			var server = new Server({
				wiki: this.commander.wiki,
				variables: listenParams
			});
			var nodeServer = server.listen();
			$tw.httpServer = {
				server: server,
				nodeServer: nodeServer,
				heartbeat: function() {
					return {
						listening: nodeServer.listening,
						address: nodeServer.address()
					};
				}
			};
			$tw.hooks.invokeHook("th-server-command-post-start", server, nodeServer, "tiddlywiki");
		}
	}
	startMCPServer(options);
	// SSE init must run after startMCPServer because that resets $tw.mcp.
	// Only enable when this process owns the HTTP server (i.e. listenMode succeeded
	// and we did not fall through to "Primary already serves HTTP" — guarded by $tw.httpServer).
	if(sseMode && $tw.httpServer) {
		var sseLib = require("$:/core/modules/server/sse-broadcaster.js");
		sseLib.initialize(this.commander.wiki);
		// Signal browser-side bootstrap that --mcp sse is active so it can
		// take over the syncadaptor; without this, the SSE adaptor stays
		// dormant and tiddlyweb's polling adaptor is used.
		// Marker lives under $:/status/ so the default SyncFilter excludes it
		// from disk persistence (otherwise a subsequent start without --mcp sse
		// would still see the stale "yes" loaded from .tid)
		this.commander.wiki.addTiddler({
			title: "$:/status/wikilabs/tw-mcp/sse-server-active",
			text: "yes"
		});
		console.error("SSE enabled at GET /events");
	}
	return null;
};

exports.Command = Command;
